"""Generate the sas7bdat codec's character-set tables from Python's codecs.

Usage (from the repository root):

    uv run --no-project --with pandas python -I -X utf8 .github/scripts/gen_sas7bdat_charsets.py

Writes ``internal/sas7bdat/charsets.mbt`` (the table the reader decodes
through, and the codes it refuses by name) and
``internal/sas7bdat/charsets_wbtest.mbt`` (spot vectors taken from the codecs
at the same time). Do not edit either by hand.

The codes are those of the reference reader's table (``encoding_names`` in
``pandas.io.sas.sas_constants``), which this script imports rather than
copies. A code page goes into the table when its codec is single-byte under
every test below; UTF-8 (code 20) is the reader's own arm.

* bytes under 0x80 decode, strictly, to the ASCII characters;
* every byte from 0x80 on decodes alone to one character (``errors="replace"``);
* no two bytes from 0x80 on decode to fewer than two characters;
* no byte carries state: for every pair (x, y), ``1B x y`` decodes to what
  its three bytes decode to alone, in order (this is what rules out the
  ISO-2022 families, whose escape sequences start with 1B).

A byte that does not decode strictly is one the code page leaves undefined:
it is spelled U+FFFD in the table, and the reader refuses it. Every
character a table entry holds must sit on the basic multilingual plane, since
the table is indexed by UTF-16 code unit.
"""

import os

import pandas.io.sas.sas_constants as sas_constants

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
TABLE_OUT = os.path.join(ROOT, "internal", "sas7bdat", "charsets.mbt")
TEST_OUT = os.path.join(ROOT, "internal", "sas7bdat", "charsets_wbtest.mbt")

UTF8_CODE = 20
REPLACEMENT = "\ufffd"


def alone(byte, codec):
    """What one byte decodes to on its own; a byte the codec leaves undefined is U+FFFD."""
    try:
        return bytes([byte]).decode(codec)
    except UnicodeDecodeError:
        return REPLACEMENT


def single_byte(codec):
    """Whether ``codec`` maps every byte to one character whatever surrounds it."""
    try:
        if bytes(range(128)).decode(codec) != bytes(range(128)).decode("ascii"):
            return False
    except UnicodeDecodeError:
        return False
    units = [alone(byte, codec) for byte in range(256)]
    if any(len(unit) != 1 for unit in units[128:]):
        return False
    for first in range(128, 256):
        for second in range(128, 256):
            if len(bytes([first, second]).decode(codec, errors="replace")) != 2:
                return False
    for x in range(256):
        for y in range(256):
            if bytes([0x1B, x, y]).decode(codec, errors="replace") != units[0x1B] + units[x] + units[y]:
                return False
    return True


def classify():
    """([(code, codec name, the 128 characters of bytes 0x80 to 0xFF)], [(code, codec name)]): decoded, refused."""
    found = []
    refused = []
    for code, codec in sorted(sas_constants.encoding_names.items()):
        if code == UTF8_CODE:
            continue
        if not single_byte(codec):
            refused.append((code, codec))
            continue
        high = ""
        for byte in range(128, 256):
            unit = alone(byte, codec)
            assert len(unit.encode("utf-16-le")) == 2, (codec, byte, unit)
            high += unit
        found.append((code, codec, high))
    return found, refused


def literal(text):
    """A MoonBit string literal: printable ASCII as is, every other unit escaped."""
    out = ['"']
    for unit in text:
        value = ord(unit)
        if 0x20 <= value <= 0x7E and unit not in ('"', "\\"):
            out.append(unit)
        else:
            out.append(f"\\u{{{value:X}}}")
    out.append('"')
    return "".join(out)


def samples(found):
    """For each page: (code, byte, the character) — one ASCII byte and three defined high bytes."""
    vectors = []
    for code, _codec, high in found:
        vectors.append((code, 0x41, "A"))
        defined = [(0x80 + k, unit) for k, unit in enumerate(high) if unit != REPLACEMENT]
        picks = sorted({0, len(defined) // 2, len(defined) - 1}) if defined else []
        for pick in picks:
            vectors.append((code, defined[pick][0], defined[pick][1]))
    return vectors


def undefined_samples(found):
    """For each page with undefined bytes: (code, byte, name) for its first and its last one."""
    vectors = []
    for code, codec, high in found:
        holes = [0x80 + k for k, unit in enumerate(high) if unit == REPLACEMENT]
        if holes:
            for byte in (holes[0], holes[-1]):
                vectors.append((code, byte, codec))
    return vectors


TABLE_HEAD = """// Generated by .github/scripts/gen_sas7bdat_charsets.py from the\n// reference reader's table of character-set codes and the single-byte codecs\n// Python names — do not edit by hand; regenerate.
//
// One entry per code page the reference reader's table names whose codec is
// single-byte: the header's character-set code, the name the table gives it,
// and the 128 characters bytes 0x80 to 0xFF spell, in order. A byte the code
// page leaves undefined is spelled U+FFFD, and the reader refuses it. Bytes
// under 0x80 are ASCII in every entry — the generator refuses a code page
// where they are not. UTF-8 (code 20) is the reader's own arm, not an entry.

///|
let charset_pages : ReadOnlyArray[CharsetPage] = [
"""

TABLE_TAIL = """]


///|
/// The codes the same table names whose characters take several bytes or
/// depend on what precedes them, with their names: the refusal names them.
let charsets_not_decoded : ReadOnlyArray[(Int, String)] = [
"""

TEST_HEAD = """// Generated by .github/scripts/gen_sas7bdat_charsets.py with the table it\n// writes — do not edit by hand; regenerate.
//
// Spot vectors taken from the codecs when the table was: a few bytes of every
// code page with the character each spells, and the bytes the page leaves
// undefined. The tests run the reader's own decoding over them; the helpers
// they use are the reader's own.

///|
/// (the header's character-set code, a byte, the character it spells).
let charset_samples : ReadOnlyArray[(Int, Int, String)] = [
"""

TEST_UNDEFINED = """]


///|
/// (the header's character-set code, a byte the code page leaves undefined,
/// the refusal's text).
let charset_undefined_samples : ReadOnlyArray[(Int, Int, String)] = [
"""

TEST_TAIL = """ ]

///|
/// The character set of `code`, or a failure saying what came out instead.
fn charset_of_or_fail(code : Int) -> Charset raise {
  let outcome : Result[Charset, @types.DataError] = Ok(charset_of(code)) catch { e => Err(e) }
  match outcome {
    Ok(charset) => charset
    Err(_) => fail("code \\{code} is refused, though the table holds it")
  }
}

///|
/// A header whose text is in the character set of `code`, or the text of
/// why there is none.
fn charset_header(code : Int) -> Result[Header, String] {
  let outcome : Result[Charset, @types.DataError] = Ok(charset_of(code)) catch { e => Err(e) }
  match outcome {
    Ok(Single(page)) =>
      Ok(
        Header::{
          wide: false,
          little: true,
          charset: Single(page),
          header_length: 1024L,
          page_length: 4096L,
          pages: 1L,
        },
      )
    Ok(Utf8) => Err("code \\{code} is UTF-8, not a table entry")
    Err(_) => Err("code \\{code} is refused, though the table holds it")
  }
}

///|
/// The byte `byte` alone at file offset 1000, decoded as the header of
/// `code` says: the text, or the refusal's.
fn charset_decode(code : Int, byte : Int) -> Result[String, String] {
  let header = match charset_header(code) {
    Ok(header) => header
    Err(text) => return Err(text)
  }
  let outcome : Result[String, @types.DataError] =
    Ok(decode_text(Bytes::makei(1, _ => byte.to_byte()), 0L, 1L, 1000L, header)) catch { e =>
      Err(e)
    }
  match outcome {
    Ok(text) => Ok(text)
    Err(@types.DataError::ParseError(@types.ParseErrorDetail::Message(text))) => Err(text)
    Err(_) => Err("not a ParseError")
  }
}

///|
test "every code page decodes its sampled bytes as the codecs do" {
  for (code, byte, expected) in charset_samples {
    assert_eq(charset_decode(code, byte), Ok(expected))
  }
}

///|
test "every table entry spells one unit per byte from 0x80 on" {
  for page in charset_pages {
    assert_eq(page.high.code_units().length(), 128)
  }
}

///|
test "a byte a code page leaves undefined refuses, naming the byte and the code page" {
  for (code, byte, expected) in charset_undefined_samples {
    assert_eq(charset_decode(code, byte), Err(expected))
  }
}

///|
test "every character set the table names and this reader does not decode refuses by name" {
  for (code, name) in charsets_not_decoded {
    let outcome : Result[Charset, @types.DataError] = Ok(charset_of(code)) catch { e => Err(e) }
    match outcome {
      Err(@types.DataError::Unsupported(text)) =>
        assert_eq(
          text,
          "sas7bdat: byte 70: the character-set field names \\{name} (code \\{code}), and this reader decodes UTF-8 (code 20) and the single-byte character sets",
        )
      _ => fail("code \\{code} did not refuse")
    }
  }
  assert_eq(charset_of_or_fail(20) is Utf8, true)
  assert_eq(charset_of_or_fail(charset_pages[0].code) is Single(_), true)
  assert_eq(charset_name(250), "an unassigned code")
}
"""


def write(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)


def main():
    found, refused = classify()
    lines = [TABLE_HEAD]
    for code, codec, high in found:
        lines.append(f"  CharsetPage::{{ code: {code}, name: {literal(codec)}, high: {literal(high)} }},\n")
    lines.append(TABLE_TAIL)
    for code, codec in refused:
        lines.append(f"  ({code}, {literal(codec)}),\n")
    lines.append("]\n")
    write(TABLE_OUT, "".join(lines))

    vectors = samples(found)
    holes = undefined_samples(found)
    lines = [TEST_HEAD]
    for code, byte, expected in vectors:
        lines.append(f"  ({code}, 0x{byte:02X}, {literal(expected)}),\n")
    lines.append(TEST_UNDEFINED)
    for code, byte, codec in holes:
        text = f"sas7bdat: byte 1000: a text field holds byte 0x{byte:02X}, which the {codec} character set leaves undefined"
        lines.append(f"  ({code}, 0x{byte:02X}, {literal(text)}),\n")
    lines.append(TEST_TAIL)
    write(TEST_OUT, "".join(lines))

    units = sum(len(high) for _c, _n, high in found)
    undefined = sum(high.count(REPLACEMENT) for _c, _n, high in found)
    print(
        f"charsets: {len(sas_constants.encoding_names)} codes in the table; {len(found)} single-byte pages "
        f"({units} units, {undefined} undefined bytes); {len(refused)} not decoded "
        f"({', '.join(str(c) for c, _n in refused)}); {len(vectors)} sample vectors, {len(holes)} undefined ones"
    )


if __name__ == "__main__":
    main()
